@extends('layouts.app', ['title' => 'Hubungi Kami | CourseUp']) @section('content')<div class="mx-auto max-w-2xl rounded-3xl border border-emerald-200 bg-white p-8"><h1 class="text-3xl font-black">Hubungi Kami</h1><p class="mt-2 text-slate-600">Punya pertanyaan atau saran? Kami siap membantu.</p><form id="contactForm" method="post" action="{{ route('contact.store') }}" class="mt-6 space-y-4">@csrf @foreach(['name'=>'Nama','email'=>'Email','phone'=>'Telepon (Opsional)','subject'=>'Subjek'] as $field => $label)<input name="{{ $field }}" type="{{ $field === 'email' ? 'email' : 'text' }}" {{ $field !== 'phone' ? 'required' : '' }} class="w-full rounded-xl border p-3" placeholder="{{ $label }}">@endforeach<textarea name="message" required rows="6" class="w-full rounded-xl border p-3" placeholder="Pesan"></textarea><button class="w-full rounded-full bg-emerald-600 py-3 text-white">Kirim Pesan</button></form><p id="contactResult" class="mt-4 hidden rounded-xl p-3"></p></div><script>document.getElementById('contactForm').addEventListener('submit',async(event)=>{event.preventDefault();const form=event.currentTarget,result=document.getElementById('contactResult');try{const response=await fetch(form.action,{method:'POST',headers:{'Accept':'application/json'},body:new FormData(form)});const data=await response.json();result.textContent=data.message;result.className='mt-4 rounded-xl p-3 '+(data.success?'bg-emerald-50 text-emerald-700':'bg-red-50 text-red-700');if(data.success)form.reset()}catch(error){result.textContent='Gagal mengirim kontak. Silakan coba lagi.';result.className='mt-4 rounded-xl bg-red-50 p-3 text-red-700'}});</script>@endsection